// ─── Ядро тем ────────────────────────────────────────────────────────────────
//
// ЧТО ЭТО. Фразы, которые уходят в урок: карточки, задания, конспект. Остальное
// из темы остаётся в разговорнике тренажёра (см. SurvivalBook.core).
//
// КАК ОТБИРАЛОСЬ. Одна фраза на смысл. В теме «Спасибо, извините» пять способов
// поблагодарить и три «не за что» — в ядро идёт 감사합니다 и 아니에요, остальные
// узнаются на слух и учатся сами, когда основная форма уже во рту. Второй
// критерий — «скажу ли я это в первый месяц»: 저기요 (окликнуть официанта) в
// ядре есть, 별말씀을요 («что вы, пустяки») нет, хотя оно вежливее.
//
// ГДЕ ЯДРО НАРОЧНО БОЛЬШЕ. Числа, еда и части тела — не набор синонимов, а
// закрытые ряды: половина счёта или семь частей тела из шестнадцати бесполезны.
// Там ядро — это полный ряд, а не десяток.
//
// ПОРЯДОК ВНУТРИ ТЕМЫ — учебный: сначала то, с чего ситуация начинается, потом
// ответ на это, потом починка. Он же становится порядком карточек в уроке.
