export const KOREAN_SURVIVAL: SurvivalBook = {
  key: 'kosv',
  title: 'Корейский: язык выживания',
  subject: 'Корейский',
  lang: 'ko',
  // Уровень намеренно назван через TOPIK I: официальной шкалы CEFR у корейского
  // нет, а фильтр «Уровень» в Конструкторе разбирает именно родную шкалу.
  level: 'С нуля → TOPIK I (бытовой минимум)',
  langName: 'корейском',
  spaced: true,
  intro:
    'Корейская вежливость — это не отдельные вежливые слова, а форма глагола: одно и то же ' +
    '«иду» звучит как 가, 가요 или 갑니다 в зависимости от того, с кем вы говорите. Весь курс ' +
    'написан на 해요체 — вежливой разговорной форме. Она уместна везде, где иностранец вообще ' +
    'открывает рот: в магазине, в такси, на стойке отеля, с незнакомым человеком на улице. ' +
    'Формы на -ㅂ니다 даны точечно, там, где их произносят все и всегда (감사합니다, 죄송합니다). ' +
    'Панмаля — обращения на «ты» — в курсе нет: незнакомому человеку так говорить нельзя, и это ' +
    'не мелочь, а грубость.',
  notes: NOTES,
  dialogs: KOSV_DIALOGS,
  phrases: withExamples(PHRASES, KO_EXAMPLES),
  core: CORE,
}

/** Сводка курса — для карточки готового курса в Конструкторе. */
export const COURSE_SUMMARY = survivalSummary(KOREAN_SURVIVAL)

/** Курс для редактора. */
export const buildKoreanSurvivalCourse = (courseId: string): CourseEdData =>
  buildSurvivalCourse(KOREAN_SURVIVAL, courseId)
